"""Comprehensive tests for retry_with_backoff expression parser."""

import pytest
from retry_with_backoff import retry_with_backoff


class TestBasicArithmetic:
    """Simple two-operand operations."""

    def test_addition(self):
        assert retry_with_backoff("2 + 3") == 5.0

    def test_subtraction(self):
        assert retry_with_backoff("10 - 4") == 6.0

    def test_multiplication(self):
        assert retry_with_backoff("3 * 7") == 21.0

    def test_division(self):
        assert retry_with_backoff("20 / 5") == 4.0

    def test_modulo(self):
        assert retry_with_backoff("17 % 5") == 2.0

    def test_exponentiation_double_star(self):
        assert retry_with_backoff("2 ** 10") == 1024.0

    def test_exponentiation_caret(self):
        assert retry_with_backoff("2 ^ 10") == 1024.0


class TestOperatorPrecedence:
    """Verify that * / % bind tighter than + -."""

    def test_multiply_before_add(self):
        assert retry_with_backoff("2 + 3 * 4") == 14.0

    def test_divide_before_subtract(self):
        assert retry_with_backoff("10 - 6 / 3") == 8.0

    def test_modulo_before_add(self):
        assert retry_with_backoff("3 + 10 % 4") == 5.0

    def test_exponent_before_multiply(self):
        assert retry_with_backoff("2 * 3 ** 2") == 18.0

    def test_chained_precedence(self):
        # 1 + 2 * 3 ** 2 = 1 + 2 * 9 = 1 + 18 = 19
        assert retry_with_backoff("1 + 2 * 3 ** 2") == 19.0

    def test_complex_precedence(self):
        # 2 * 3 + 4 * 5 = 6 + 20 = 26
        assert retry_with_backoff("2 * 3 + 4 * 5") == 26.0

    def test_mixed_modulo_and_multiply(self):
        # 10 % 3 * 4 = 1 * 4 = 4
        assert retry_with_backoff("10 % 3 * 4") == 4.0


class TestAssociativity:
    """Verify left-associativity for +/-/*/÷ and right-associativity for **."""

    def test_subtraction_left_assoc(self):
        # 10 - 3 - 2 = 7 - 2 = 5
        assert retry_with_backoff("10 - 3 - 2") == 5.0

    def test_division_left_assoc(self):
        # 24 / 4 / 2 = 6 / 2 = 3.0
        assert retry_with_backoff("24 / 4 / 2") == 3.0

    def test_exponentiation_right_assoc(self):
        # 2 ** 3 ** 2 = 2 ** 9 = 512
        assert retry_with_backoff("2 ** 3 ** 2") == 512.0

    def test_caret_right_assoc(self):
        assert retry_with_backoff("2 ^ 3 ^ 2") == 512.0


class TestParentheses:
    """Parentheses override precedence."""

    def test_simple_parens(self):
        assert retry_with_backoff("(2 + 3) * 4") == 20.0

    def test_nested_parens(self):
        assert retry_with_backoff("((2 + 3) * 4)") == 20.0

    def test_deeply_nested(self):
        assert retry_with_backoff("((((1 + 1))))") == 2.0

    def test_parens_change_exponent(self):
        # (2 * 3) ** 2 = 6 ** 2 = 36
        assert retry_with_backoff("(2 * 3) ** 2") == 36.0

    def test_complex_parens(self):
        # (2 + 3) * (4 - 1) = 5 * 3 = 15
        assert retry_with_backoff("(2 + 3) * (4 - 1)") == 15.0


class TestUnaryOperators:
    """Unary minus and plus."""

    def test_unary_minus(self):
        assert retry_with_backoff("-5") == -5.0

    def test_unary_plus(self):
        assert retry_with_backoff("+5") == 5.0

    def test_unary_minus_in_expression(self):
        assert retry_with_backoff("3 + -2") == 1.0

    def test_double_unary_minus(self):
        assert retry_with_backoff("--5") == 5.0

    def test_unary_minus_with_paren(self):
        assert retry_with_backoff("-(3 + 2)") == -5.0

    def test_unary_minus_before_exponent(self):
        # -2 ** 2 = -(2 ** 2) = -4
        assert retry_with_backoff("-2 ** 2") == -4.0


class TestFloatingPoint:
    """Decimal numbers and float arithmetic."""

    def test_float_addition(self):
        assert retry_with_backoff("1.5 + 2.5") == 4.0

    def test_float_multiplication(self):
        assert pytest.approx(retry_with_backoff("0.1 * 3")) == 0.3

    def test_integer_division_result(self):
        assert retry_with_backoff("7 / 2") == 3.5

    def test_scientific_notation(self):
        assert retry_with_backoff("1e3 + 500") == 1500.0

    def test_scientific_notation_negative_exp(self):
        assert pytest.approx(retry_with_backoff("5e-2")) == 0.05

    def test_leading_dot(self):
        assert retry_with_backoff(".5 + .5") == 1.0

    def test_trailing_dot(self):
        assert retry_with_backoff("5. + 3.") == 8.0


class TestWhitespace:
    """Expressions should tolerate arbitrary spacing."""

    def test_no_spaces(self):
        assert retry_with_backoff("2+3*4") == 14.0

    def test_extra_spaces(self):
        assert retry_with_backoff("  2   +   3  ") == 5.0

    def test_tabs(self):
        assert retry_with_backoff("2\t*\t3") == 6.0

    def test_empty_parens_content(self):
        assert retry_with_backoff("( 2 + 3 )") == 5.0


class TestSingleValue:
    """A lone number is a valid expression."""

    def test_integer(self):
        assert retry_with_backoff("42") == 42.0

    def test_float(self):
        assert retry_with_backoff("3.14") == 3.14

    def test_zero(self):
        assert retry_with_backoff("0") == 0.0


class TestEdgeCases:
    """Boundary conditions and tricky inputs."""

    def test_large_number(self):
        assert retry_with_backoff("999999999 * 999999999") == pytest.approx(999999998000000001.0)

    def test_nested_exponent_parens(self):
        # (2 ** 3) ** 2 = 8 ** 2 = 64
        assert retry_with_backoff("(2 ** 3) ** 2") == 64.0

    def test_chained_modulo(self):
        # 100 % 30 % 7 = 10 % 7 = 3
        assert retry_with_backoff("100 % 30 % 7") == 3.0

    def test_complex_real_world(self):
        # a = 2 + 3 * 4 ** 2 / 8 - 1
        # = 2 + 3 * 16 / 8 - 1
        # = 2 + 48 / 8 - 1
        # = 2 + 6 - 1
        # = 7
        assert retry_with_backoff("2 + 3 * 4 ** 2 / 8 - 1") == 7.0

    def test_all_operators(self):
        # 10 + 5 - 3 * 2 / 1 % 4 ** 2
        # = 10 + 5 - 3 * 2 / 1 % 16
        # = 10 + 5 - 6 / 1 % 16
        # = 10 + 5 - 6 % 16
        # = 10 + 5 - 6
        # = 9
        assert retry_with_backoff("10 + 5 - 3 * 2 / 1 % 4 ** 2") == 9.0


class TestErrorHandling:
    """Malformed expressions should raise ValueError or ZeroDivisionError."""

    def test_empty_expression(self):
        with pytest.raises(ValueError):
            retry_with_backoff("")

    def test_only_operator(self):
        with pytest.raises(ValueError):
            retry_with_backoff("+")

    def test_missing_operand(self):
        with pytest.raises(ValueError):
            retry_with_backoff("2 +")

    def test_trailing_operator(self):
        with pytest.raises(ValueError):
            retry_with_backoff("2 + 3 *")

    def test_unmatched_open_paren(self):
        with pytest.raises(ValueError):
            retry_with_backoff("(2 + 3")

    def test_unmatched_close_paren(self):
        with pytest.raises(ValueError):
            retry_with_backoff("2 + 3)")

    def test_empty_parens(self):
        with pytest.raises(ValueError):
            retry_with_backoff("()")

    def test_division_by_zero(self):
        with pytest.raises(ZeroDivisionError):
            retry_with_backoff("1 / 0")

    def test_modulo_by_zero(self):
        with pytest.raises(ZeroDivisionError):
            retry_with_backoff("10 % 0")

    def test_invalid_character(self):
        with pytest.raises(ValueError, match="Unexpected character"):
            retry_with_backoff("2 & 3")

    def test_double_dot_number(self):
        with pytest.raises(ValueError, match="Invalid number"):
            retry_with_backoff("1.2.3 + 1")

    def test_consecutive_operators_invalid(self):
        with pytest.raises(ValueError):
            retry_with_backoff("2 + * 3")

    def test_letters_as_expression(self):
        with pytest.raises(ValueError):
            retry_with_backoff("abc")

